export interface AgentScope {
  filePatterns?: string[];         // globs de archivos que puede tocar
  contextTypes?: string[];         // tipos de contexto que recibe
  capabilities: AgentCapability[]; // capacidades permitidas en este scope
}

export interface AgentManifestEntry {
  profile: AgentProfile;
  scope: AgentScope;
  restrictions?: string[];         // reglas explícitas de lo que NO puede hacer
  contextFilter?: ContextPriority; // prioridad mínima de contexto que recibe
}

export interface ProjectContextSnapshot {
  name: string | null;
  version: string | null;
  primaryFramework: string | null;
  language: string;
  branch: string | null;
  hasTests: boolean;
  hasLinting: boolean;
}

export interface AgentManifest {
  manifestVersion: '1.0.0';
  generatedAt: string;
  projectRoot: string;
  projectContext: ProjectContextSnapshot;
  agents: AgentManifestEntry[];
  complianceScore?: number;           // 0-100, si hay complianceReport
  criticalIssueCount?: number;
  contextSpecVersion: string;
}

Agregar un registro de múltiples agentes junto al agente principal:

private agents: AgentManifestEntry[] = [];

addAgent(entry: AgentManifestEntry): void {
  this.agents.push(entry);
  // Si solo hay un agente, también lo setea como el agent principal del output
  if (this.agents.length === 1) {
    this.agent = entry.profile;
  }
}

NOTA: setAgent() sigue funcionando para el caso simple de un solo agente.

Función privada que extrae los datos clave del output para el snapshot:

private buildProjectSnapshot(output: ContextOutput): ProjectContextSnapshot {
  const pkg = output.contexts.find(c => c.type === 'package-json')?.data;
  const git = output.contexts.find(c => c.type === 'git')?.data;
  const stack = (pkg as any)?.stack;

  return {
    name: (pkg as any)?.name ?? null,
    version: (pkg as any)?.version ?? null,
    primaryFramework: stack?.primaryFramework ?? null,
    language: stack?.language ?? 'unknown',
    branch: (git as any)?.currentBranch ?? null,
    hasTests: stack?.hasTests ?? false,
    hasLinting: stack?.hasLinting ?? false,
  };
}

async toAgentManifest(): Promise<AgentManifest> {
  const output = await this.collectContext();
  const projectContext = this.buildProjectSnapshot(output);

  return {
    manifestVersion: '1.0.0',
    generatedAt: new Date().toISOString(),
    projectRoot: process.cwd(), // o el root del proyecto si está disponible
    projectContext,
    agents: this.agents,
    complianceScore: output.complianceReport?.overallScore,
    criticalIssueCount: output.complianceReport?.criticalIssues?.length,
    contextSpecVersion: this.specVersion,
  };
}

